with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('anden', 'word', 'f757ebda-2048-5c6d-9f0f-141678f6f5f1', 1, 'adjective', null, 'other, different', 'Vi kan tage en anden vej hjem.', 'We can take a different way home.'), ('anden', 'word', 'fbb68cda-a342-527d-95bd-871f76d9ce23', 2, 'numeral', null, 'second (in a sequence)', 'Hun kom på en anden plads i løbet.', 'She came second in the race.'), ('medens', 'word', '8f2dcb43-27aa-5dbb-b916-457fd6066e59', 1, 'conjunction', null, 'while, whereas', 'Han lavede mad, medens hun dækkede bordet.', 'He was cooking while she set the table.'), ('århundred', 'word', 'd0fb7aeb-413b-520e-bf49-2635d2373e0c', 1, 'noun', null, 'century', 'Bygningen er mere end et århundred gammel.', 'The building is more than a century old.'), ('broder', 'word', 'e2dcb927-6a43-5ef2-93a0-e443db8a21e4', 1, 'noun', null, 'brother', 'Han rejste sammen med sin broder til udlandet.', 'He travelled abroad together with his brother.'), ('gymnasie', 'word', 'ecb99c18-df57-548b-abe5-161f1b17005f', 1, 'noun', null, 'upper secondary school, gymnasium', 'Hun begynder på gymnasie til august.', 'She starts at upper secondary school in August.'), ('grundliggende', 'word', '60e4a357-5b0a-5bd3-b136-ca8a6562e92d', 1, 'adjective', null, 'fundamental, basic', 'Det er et grundliggende princip i dansk lov.', 'It is a fundamental principle of Danish law.'), ('ministerie', 'word', 'e1e70fd0-288a-5d4a-b9eb-a92cf2e99eff', 1, 'noun', null, 'ministry', 'Hun arbejder i et ministerie i København.', 'She works in a ministry in Copenhagen.'), ('nøje', 'word', '9975b2f9-452b-5b3e-993b-8b7f600a5321', 1, 'adjective', null, 'meticulous, precise', 'Han er meget nøje med detaljerne.', 'He is very meticulous about details.'), ('årevis', 'word', '8010a043-3db8-5c61-87be-ec6455827f15', 1, 'adjective', null, 'lasting for years', 'De boede der i årevis.', 'They lived there for years.'), ('udenrigsministerie', 'word', 'e1a27cb4-e1d5-5875-89