l, 'citizen (of a country)', 'Han er dansk statsborger.', 'He is a Danish citizen.'), ('problemstilling', 'word', '77618b01-536d-5247-b1b8-1f68539c10ed', 1, 'noun', null, 'framing of a problem, issue', 'Rapporten beskriver en vigtig problemstilling.', 'The report describes an important issue.'), ('forsvarer', 'word', '5af418d3-28c3-5dae-aad4-54da69c3d60b', 1, 'noun', null, 'defence lawyer, defender', 'Hendes forsvarer talte i retten.', 'Her defence lawyer spoke in court.'), ('pille', 'word', '1bf19444-0004-50f6-8776-f89bd865e44f', 1, 'verb', null, 'to pick at, to fiddle with', 'Lad være med at pille ved såret.', 'Do not pick at the wound.'), ('pille', 'word', '7c70573a-b114-5329-97e3-7a9e7f56075f', 2, 'noun', null, 'pill, tablet', 'Han tog en pille mod hovedpine.', 'He took a pill for his headache.'), ('real', 'word', 'e7ac50d9-5e50-554a-a895-de399bacc21f', 1, 'adjective', null, 'real, actual', 'Det er et real problem, vi må løse.', 'It is a real problem we have to solve.'), ('kendetegne', 'word', 'd7d42cde-3101-5a14-bdae-e464044e40a1', 1, 'verb', null, 'to characterize, to be typical of', 'Høj kvalitet kendetegner deres produkter.', 'High quality characterizes their products.'), ('taske', 'word', '3d6b35c5-d5fd-5267-93b5-c203f9c82dc7', 1, 'noun', null, 'bag', 'Hun glemte sin taske i bussen.', 'She forgot her bag on the bus.'), ('guide', 'word', '0b21a6d6-171a-5037-9ad4-9bfc699fa205', 1, 'noun', null, 'guide (person)', 'Vores guide viste os rundt i byen.', 'Our guide showed us around the city.'), ('guide', 'word', 'bb70afc7-563d-5837-a73c-85fcb05f43d1', 2, 'noun', null, 'guide, guidebook', 'Vi købte en guide til byen.', 'We bought a guidebook to the city.'), ('anklager', 'word', '69a29d45-9529-5de9-a10b-848873438672', 1, 'noun', null, 'prosecutor', 'Anklager fremlagde sagen for retten.', 'The prosecutor presented the case to the court.'), ('dannelse', 'word', '8d5835f0-4bbc-58cb-aee7-2ab3eb080797', 1, 'noun', null, 'upbringing, good manners, culture', 'God dannelse 