oject.'), ('overensstemmelse', 'word', '58451f2f-6148-5778-88d9-68a5cbea2400', 1, 'noun', null, 'accordance, agreement', 'Beslutningen blev truffet i overensstemmelse med loven.', 'The decision was made in accordance with the law.'), ('interviewe', 'word', '170b31be-e80a-5349-b4c8-528aaab3a3d5', 1, 'verb', null, 'to interview', 'Journalisten ville interviewe ministeren.', 'The journalist wanted to interview the minister.'), ('socialistisk', 'word', '31067abe-9492-54e6-9981-e2c1ee65c53a', 1, 'adjective', null, 'socialist', 'Partiet fører en socialistisk politik.', 'The party pursues a socialist policy.'), ('udskifte', 'word', '8cd874cf-6458-56b9-bef7-a26e0e8884f8', 1, 'verb', null, 'to replace', 'Vi skal udskifte det gamle vindue.', 'We need to replace the old window.'), ('kommunikere', 'word', '72fb6a41-2852-5f04-a390-fcfed1baa319', 1, 'verb', null, 'to communicate', 'De kommunikerer på engelsk.', 'They communicate in English.'), ('bestræbelse', 'word', '0924267f-9ee7-5768-8333-a930339ee2ca', 1, 'noun', null, 'effort, endeavour', 'Hendes bestræbelse på at hjælpe blev bemærket.', 'Her effort to help was noticed.'), ('pilot', 'word', 'a64a1a42-7874-552d-9e6e-0d8b85af64ac', 1, 'noun', null, 'pilot', 'Piloten landede flyet sikkert.', 'The pilot landed the plane safely.'), ('måltid', 'word', '4e117b30-6d0f-53e4-989a-70d23c8d6181', 1, 'noun', null, 'meal', 'Familien spiste deres måltid sammen.', 'The family ate their meal together.'), ('stole', 'word', 'b7fb4f16-ffc2-57f1-8647-00e48662030f', 1, 'verb', null, 'to trust, to rely on', 'Du kan altid stole på mig.', 'You can always rely on me.'), ('udspille', 'word', 'ac308ed4-e961-50ba-87c4-9d4be719a888', 1, 'verb', null, 'to play out, to unfold (of events)', 'Dramaet vil udspille sig i denne uge.', 'The drama will unfold this week.'), ('samvittighed', 'word', '4bef3e30-0321-54cb-b426-0a84f2226e1b', 1, 'noun', null, 'conscience', 'Han fik dårlig samvittighed over løgnen.', 'He got a bad conscience over the lie.'), ('tøve', 'word', 'aa2e6bb5-5cb2-5407-8e0b-de22a376cb64', 1, 'verb', null, 'to hesitate', 'Hun begyndte at tøve med sit svar.', 'She began to hesitate with her answer.'), ('såmænd', 'word', '297d16af-cb08-57c1-b4ce-12d379780cc7', 1, 'adverb', null, 'indeed, actually (colloquial assurance)', 'Det går såmænd meget godt.', 'Things are indeed going very well.'), ('skrige', 'word', '7dfa8a79-c1fe-5a2d-b2cf-a587dd7c25b1', 1, 'verb', null, 'to scream, to shriek', 'Barnet begyndte pludselig at skrige.', 'The child suddenly started to scream.'), ('hidtidig', 'word', 'dc0b0907-53ae-5bd1-a5ee-70e9bd26ecbf', 1, 'adjective', null, 'former, previous (until now)', 'Den hidtidige leder stoppede i går.', 'The previous manager left yesterday.'), ('fatte', 'word', 'd0af2fc4-c9ad-51ed-b338-e6b92bfd96c3', 1, 'verb', null, 'to grasp, to comprehend', 'Jeg kan slet ikke fatte, hvad der skete.', 'I simply cannot grasp what happened.'), ('strømme', 'word', '811e9985-e640-5cb8-8897-35029a999ef8', 1, 'verb', null, 'to stream, to flow; to flock (of people)', 'Vandet begyndte at strømme ud af røret.', 'The water began to stream out of the pipe.'), ('diagnose', 'word', '30b74f4a-8446-5648-8ca5-27d793d2f637', 1, 'noun', null, 'diagnosis', 'Lægen stillede en klar diagnose.', 'The doctor made a clear diagnosis.'), ('spørgsmålstegn', 'word', 'db78ddad-eb58-5a30-b8e5-2e1d2460f802', 1, 'noun', null, 'question mark', 'Sætningen slutter med et spørgsmålstegn.', 'The sentence ends with a question mark.'), ('informere', 'word', 'ef8d5fed-467a-5894-ad12-dbdc79fa3dba', 1, 'verb', null, 'to inform', 'Vi vil informere jer om ændringerne.', 'We will inform you of the changes.'), ('hjul', 'word', 'b0c13406-0bc7-57e2-b5ef-77c372329cc9', 1, 'noun', null, 'wheel', 'Cyklens forreste hjul var punkteret.', 'The bicycle''s front wheel had a puncture.'), ('snæver', 'word', '10eb56a1-b012-5182-aaaf-094ef50e5d83', 1, 'adjective', null, 'narrow, cramped', 'De boede i en snæver lejlighed.', 'They lived in a cramped apartment.'), ('udøv